using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"),
     Description("Summarizes the provided text at the requested detail level.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Detail level: brief, standard, or detailed (default: standard)")]
        string detail = "standard")
    {
        return
        [
            new McpServerPromptMessage(
                McpServerPromptMessageRole.User,
                new ModelContextProtocol.Protocol.Types.Content
                {
                    Type = "text",
                    Text = $"""
                        Summarize the following text at a "{detail}" level of detail.

                        - brief: 1-2 sentences
                        - standard: a short paragraph
                        - detailed: multiple paragraphs with key points

                        Text:
                        {text}
                        """
                })
        ];
    }
}

